<script setup lang="ts">
import PluginMarket from '../components/PluginMarket.vue'
import PluginRenderer from '../components/PluginRenderer.vue'
import{ref,onMounted}from'vue';import{request,post}from'../api/client';import{ElMessageBox,ElMessage}from'element-plus';import{Upload,Setting,VideoPlay,Delete,Clock}from'@element-plus/icons-vue'
interface Field{key:string;label:string;type:string;required?:boolean;default?:string;options?:string[]}
interface Manifest{commands?:{id:string;name:string;description?:string}[];services?:{id:string;name:string;intervalSeconds:number}[];pages?:{id:string;title:string}[];routes?:{path:string;method:string}[];outbound?:string[];permissions?:string[];dashboard?:boolean;id:string;name:string;version:string;contractVersion:number;runtime:"wasm";settings?:Field[];capabilities:string[]}
interface Plugin{manifest:Manifest;enabled:boolean;revision:number;packageDigest?:string}
interface Package{manifest:Manifest;digest:string;files:string[];readme:string}
const cloneOpen=ref(false),cloneID=ref(''),cloneName=ref('')
const dataOpen=ref(false)
const items=ref<Plugin[]>([]),busy=ref(false),error=ref(''),file=ref<File|null>(null),preview=ref<Package|null>(null),previewOpen=ref(false),configOpen=ref(false),selected=ref<Plugin|null>(null),values=ref<Record<string,string>>({}),secretFields=ref<string[]>([]),clearSecrets=ref<string[]>([]),configRevision=ref(0),testOpen=ref(false),filename=ref(''),result=ref<unknown>(null),runs=ref<Array<Record<string,unknown>>>([]),runsOpen=ref(false)
const isSecret=(f:Field)=>f.type==='password'||/(password|token|secret|api.?key|authorization|cookie)/i.test(f.key)
async function load(){try{items.value=await request('/plugins')}catch(e){error.value=e instanceof Error?e.message:'插件读取失败'}}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;preview.value=null}
async function packageCall(install:boolean){if(!file.value)return;busy.value=true;error.value='';try{const form=new FormData();form.append('package',file.value);if(install&&preview.value){form.append('digest',preview.value.digest);form.append('confirm','true');form.append('revision',String(items.value.find(x=>x.manifest.id===preview.value?.manifest.id)?.revision??0))}const out=await request<Package>('/plugins/package'+(install?'':'?preview=true'),{method:'POST',body:form});if(install){previewOpen.value=false;preview.value=null;file.value=null;await load();ElMessage.success('插件包已安装，当前停用；升级后的设置需核对后重新启用。')}else{preview.value=out;previewOpen.value=true}}catch(e){error.value=e instanceof Error?e.message:'插件包无效'}finally{busy.value=false}}
async function clone(){if(!selected.value)return;busy.value=true;try{await post(`/plugins/${selected.value.manifest.id}/clone`,{id:cloneID.value,name:cloneName.value,revision:selected.value.revision,confirm:true});cloneOpen.value=false;await load();ElMessage.success('已创建停用分身，配置与数据相互隔离')}catch(e){error.value=String(e)}finally{busy.value=false}}
async function runService(item:Plugin,key:string){try{await ElMessageBox.confirm('立即运行一次服务？仅执行已启用插件的当前修订，不自动重发。','插件服务',{confirmButtonText:'确认运行',cancelButtonText:'取消'});await post(`/plugins/${item.manifest.id}/services/${key}`,{confirm:true,revision:item.revision});ElMessage.success('服务任务已入队')}catch(e){if(e instanceof Error)error.value=e.message}}
async function data(item:Plugin){selected.value=item;try{result.value=await request(`/plugins/${item.manifest.id}/state`);dataOpen.value=true}catch(e){error.value=String(e)}}
async function clearData(){if(!selected.value)return;try{await ElMessageBox.confirm('清理本插件持久数据并停用？不会删除媒体。','清理插件数据',{confirmButtonText:'确认清理',cancelButtonText:'取消'});await request(`/plugins/${selected.value.manifest.id}/data`,{method:'DELETE',body:JSON.stringify({confirm:true,revision:selected.value.revision})});dataOpen.value=false;await load()}catch(e){if(e instanceof Error)error.value=e.message}}
async function toggle(item:Plugin){try{if(!item.enabled)await ElMessageBox.confirm(`启用WASM沙箱插件？宿主能力：${item.manifest.permissions?.join('、')||'无'}；外部访问目标：${item.manifest.outbound?.join('、')||'无'}。仅授权列出的能力，不提供宿主文件、环境变量或Shell。`,'启用插件',{type:'warning',confirmButtonText:'授权并启用',cancelButtonText:'取消'});await post('/plugins',{manifest:item.manifest,enabled:!item.enabled,consent:true,revision:item.revision});await load()}catch(e){if(e instanceof Error)error.value=e.message}}
async function configure(item:Plugin){selected.value=item;clearSecrets.value=[];try{const config=await request<{values:Record<string,string>;secretFields:string[];revision:number}>(`/plugins/${item.manifest.id}/settings`);values.value=config.values;secretFields.value=config.secretFields;configRevision.value=config.revision;for(const f of item.manifest.settings??[])if(values.value[f.key]===undefined)values.value[f.key]=isSecret(f)?'':f.default??'';configOpen.value=true}catch(e){error.value=e instanceof Error?e.message:'设置读取失败'}}
async function saveConfig(){if(!selected.value)return;busy.value=true;try{await request(`/plugins/${selected.value.manifest.id}/settings`,{method:'PUT',body:JSON.stringify({values:values.value,clear:clearSecrets.value,revision:configRevision.value})});configOpen.value=false;await load();ElMessage.success('配置已加密保存，插件已停用；确认新配置后重新启用。')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function remove(item:Plugin){try{await ElMessageBox.confirm(`卸载 ${item.manifest.name}？会删除插件设置和执行记录，不删除媒体。`,'卸载插件',{confirmButtonText:'确认卸载',cancelButtonText:'取消',type:'warning'})}catch{return};try{await request(`/plugins/${item.manifest.id}?confirm=true&revision=${item.revision}`,{method:'DELETE'});await load()}catch(e){error.value=e instanceof Error?e.message:'卸载失败'}}
async function test(){if(!selected.value)return;try{await ElMessageBox.confirm('执行一次明确的插件测试？远程插件会收到测试数据及本插件配置；不会修改真实媒体，也不会自动重试。','测试插件',{confirmButtonText:'确认测试',cancelButtonText:'取消'})}catch{return};busy.value=true;result.value=null;try{result.value=await post(`/plugins/${selected.value.manifest.id}/test`,{filename:filename.value,confirm:true})}catch(e){error.value=e instanceof Error?e.message:'测试失败'}finally{busy.value=false}}
async function history(item:Plugin){selected.value=item;try{runs.value=await request(`/plugins/${item.manifest.id}/runs`);runsOpen.value=true}catch(e){error.value=e instanceof Error?e.message:'记录读取失败'}}
onMounted(load)
</script>
<template><section class="page-heading"><div><span class="page-kicker">SYSTEM / 扩展</span><h1>插件扩展</h1><p>可执行 WASM 插件 · ZIP 安装、设置、启停、升级、测试及卸载。</p></div><el-button @click="load">刷新插件</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<PluginMarket @installed="load"/><section class="panel section-gap"><div class="panel-title"><h2>安装 / 升级插件包</h2><span class="muted">ZIP ≤ 8 MiB · 解包 ≤ 24 MiB</span></div><p class="field-hint">必须包含 manifest.json 和可执行的 plugin.wasm，可附 settings.json、README.md、ui.html。仅支持 WASM 沙箱代码，不支持旧 Webhook、规则型插件或手填 Manifest。安装及升级后默认停用。</p><div class="package-upload"><label for="plugin-package">选择ZIP插件包</label><input id="plugin-package" type="file" accept=".zip,application/zip" @change="pick"/><el-button :icon="Upload" type="primary" :loading="busy" :disabled="!file" @click="packageCall(false)">预览插件包</el-button></div></section>
<section class="panel section-gap sandbox-summary" aria-label="插件沙箱说明"><div class="panel-title"><h2>沙箱执行边界</h2><el-tag>WASM / WASI</el-tag></div><p>64 MiB 线性内存 · 单次执行最多 4 秒 · 输出不超过 256 KiB。默认无法访问宿主文件、环境变量、网络或 Shell；网络和业务能力必须声明并经管理员授权。</p><p class="field-hint">0day 文件名识别与电影 / 剧集命名模板属于主程序基本功能，无需安装插件。命名模板在系统设置中配置。</p><RouterLink to="/settings" class="inline-link">打开系统设置</RouterLink></section>
<section v-if="!items.length" class="panel section-gap plugin-empty" role="status"><h2>尚未安装插件</h2><p>主程序基本功能已可使用。需要扩展时，从市场选择插件或上传包含 WASM 代码的 ZIP 包。</p></section><section v-else class="plugin-grid"><article v-for="item in items" :key="item.manifest.id" class="panel"><div class="panel-title"><h2>{{item.manifest.name}}</h2><el-tag>{{item.enabled?'已启用':'停用'}}</el-tag></div><p class="muted">{{item.manifest.id}} · {{item.manifest.version}} · WASM 沙箱</p><p>{{item.manifest.capabilities.join('、')}}</p><p v-if="item.packageDigest" class="field-hint">已安装ZIP · {{item.packageDigest.slice(0,12)}}</p><div class="plugin-actions"><el-button @click="toggle(item)">{{item.enabled?'停用扩展':'授权并启用'}}</el-button><el-button :icon="Setting" @click="configure(item)">设置</el-button><el-button :icon="VideoPlay" :disabled="!item.enabled" @click="selected=item;filename='';result=null;testOpen=true">测试</el-button><el-button :icon="Clock" @click="history(item)">记录</el-button><el-button @click="selected=item;cloneID='';cloneName='';cloneOpen=true">创建分身</el-button><el-button @click="data(item)">数据 / 状态</el-button><RouterLink v-for="page in item.manifest.pages??[]" :key="page.id" :to="`/plugins/${item.manifest.id}/${page.id}`" class="inline-link">{{page.title}}</RouterLink><el-button v-for="service in item.manifest.services??[]" :key="service.id" :disabled="!item.enabled" @click="runService(item,service.id)">运行 {{service.name}}</el-button><el-button :icon="Delete" type="danger" plain @click="remove(item)">卸载</el-button></div></article></section>
<el-dialog v-model="previewOpen" title="插件包安装预览" width="min(760px,94vw)" :close-on-click-modal="false"><h2>{{preview?.manifest.name}} · {{preview?.manifest.version}}</h2><p class="field-hint">可执行 WASM · 沙箱隔离 · {{preview?.manifest.capabilities.join('、')}}</p><code>{{preview?.digest}}</code><p>包含：{{preview?.files.join('、')}}</p><pre class="plugin-readme">{{preview?.readme||'没有附说明文档'}}</pre><p class="field-hint">安装/升级不会自动启用；如已有同ID插件，会保留兼容配置并停用。</p><template #footer><el-button @click="previewOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="packageCall(true)">确认安装或升级</el-button></template></el-dialog>
<el-dialog v-model="configOpen" :title="`${selected?.manifest.name} 插件设置`" width="min(650px,94vw)" :close-on-click-modal="false"><form class="connection-form" @submit.prevent="saveConfig"><template v-for="f in selected?.manifest.settings??[]" :key="f.key"><label :for="'plugin-setting-'+f.key">{{f.label}}{{f.required?'（必填）':''}}</label><el-select v-if="f.type==='select'" :id="'plugin-setting-'+f.key" v-model="values[f.key]"><el-option v-for="x in f.options" :key="x" :label="x" :value="x"/></el-select><el-select v-else-if="f.type==='boolean'" :id="'plugin-setting-'+f.key" v-model="values[f.key]"><el-option label="启用" value="true"/><el-option label="关闭" value="false"/></el-select><el-input v-else :id="'plugin-setting-'+f.key" v-model="values[f.key]" :type="isSecret(f)?'password':f.type==='textarea'?'textarea':f.type==='date'?'date':'text'" :show-password="isSecret(f)" :maxlength="2000" :autocomplete="isSecret(f)?'new-password':'off'" :placeholder="secretFields.includes(f.key)?'已设置；留空保持原值':''"/><el-checkbox v-if="isSecret(f)&&secretFields.includes(f.key)" v-model="clearSecrets" :value="f.key">明确清除 {{f.label}}</el-checkbox></template><p v-if="!selected?.manifest.settings?.length" class="field-hint">此插件没有自定义设置字段。</p><p class="field-hint">所有设置仍加密存储，管理员后台显示原始配置。保存会停用插件，需核对后重新启用。</p><el-button type="primary" native-type="submit" :loading="busy">保存插件设置</el-button></form></el-dialog>
<el-dialog v-model="testOpen" title="测试插件（不修改媒体）" width="min(740px,94vw)"><label for="plugin-test-filename">测试文件名</label><el-input id="plugin-test-filename" v-model="filename" :maxlength="1024" placeholder="输入自有测试文件名，不选择真实文件"/><el-button :loading="busy" @click="test">执行测试</el-button><pre class="plugin-readme">{{result?JSON.stringify(result,null,2):'尚未运行测试'}}</pre></el-dialog>
<el-dialog v-model="cloneOpen" title="创建插件分身" width="min(600px,94vw)"><p>复制当前插件代码和配置（包括秘密值），新实例默认停用；持久数据与定时服务独立。</p><label>分身ID<el-input v-model="cloneID" aria-label="插件分身ID" placeholder="小写字母、数字、连字符"/></label><label>名称<el-input v-model="cloneName" aria-label="插件分身名称"/></label><template #footer><el-button @click="cloneOpen=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!cloneID||!cloneName" @click="clone">确认创建停用分身</el-button></template></el-dialog><el-dialog v-model="dataOpen" title="插件数据与状态" width="min(760px,94vw)"><pre class="plugin-readme">{{JSON.stringify(result,null,2)}}</pre><el-button type="danger" plain @click="clearData">清理本插件数据并停用</el-button></el-dialog><el-dialog v-model="runsOpen" title="插件最近执行记录" width="min(740px,94vw)"><el-table :data="runs" empty-text="暂无执行记录"><el-table-column prop="kind" label="事件"/><el-table-column prop="state" label="状态"/><el-table-column prop="message" label="提示"/><el-table-column prop="createdAt" label="时间"/></el-table></el-dialog>
</template>
<style scoped>.sandbox-summary p,.plugin-empty p{line-height:1.7;margin-block:12px}.sandbox-summary .inline-link{display:inline-flex;align-items:center;min-height:44px}.plugin-actions :deep(.el-button){min-height:44px}.plugin-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin-bottom:24px}.plugin-grid p{margin:12px 0;line-height:1.7}.plugin-grid code{display:block;overflow-wrap:anywhere}.plugin-actions,.package-upload{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.plugin-actions .el-button+.el-button{margin-left:0}.package-upload input{max-width:100%}.plugin-readme{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;background:#151b23;color:#e5e9f0;padding:16px;border-radius:8px;line-height:1.8}.el-textarea{margin:16px 0}summary{cursor:pointer;font-size:14px;font-weight:600;min-height:44px}</style>
